import React, { useState, useEffect } from 'react';
import {
  getStaffFaceTrainingRequest,
  resetGetStaffFaceTraining,
} from '../../redux/staff-facetraining/actions';
import { getBranchRequest, resetGetBranch } from '../../redux/actions';
import {
  Card,
  Row,
  Col,
  Form,
  Button,
  Badge,
  Modal,
  ProgressBar,
  Tabs,
  Tab,
  ListGroup,
  Image,
  Container,
  Spinner,
  Alert,
} from 'react-bootstrap';
import {
  FaCamera,
  FaCheckCircle,
  FaTimesCircle,
  FaFilter,
  FaImages,
  FaRegSmile,
  FaExclamationTriangle,
  FaDownload,
  FaUser,
  FaBuilding,
  FaIdCard,
  FaSync,
} from 'react-icons/fa';
import moment from 'moment';
import noProfile from '../../assets/images/noprofile_images.jpg';
import { usePageTitle, useRedux } from '../../hooks';
import { showMessage } from '../../utils/AllFunction';

const Index = () => {
  usePageTitle({
    title: 'Face Training',
    breadCrumbItems: [
      {
        path: '/staff/face-training',
        label: 'Staff',
      },
      {
        path: '/staff/face-training',
        label: 'Face Training',
        active: true,
      },
    ],
  });

  const { dispatch, appSelector } = useRedux();
  
  // Redux state
  const {
    getBranchSuccess,
    getBranchList,
    getBranchFailure,
    getStaffFaceTrainingList,
    isLoading,
    getStaffFaceTrainingSuccess,
    getStaffFaceTrainingFailure,
    errorMessage,
  } = appSelector((state) => ({
    getStaffFaceTrainingList: state.faceTrainingReducer.getStaffFaceTrainingList,
    isLoading: state.faceTrainingReducer.isLoading,
    getStaffFaceTrainingSuccess: state.faceTrainingReducer.getStaffFaceTrainingSuccess,
    getStaffFaceTrainingFailure: state.faceTrainingReducer.getStaffFaceTrainingFailure,
    errorMessage: state.faceTrainingReducer.errorMessage,
    getBranchSuccess: state.branchReducer.getBranchSuccess,
    getBranchList: state.branchReducer.getBranchList,
    getBranchFailure: state.branchReducer.getBranchFailure,
  }));

  // Local state
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [showImageModal, setShowImageModal] = useState(false);
  const [selectedImage, setSelectedImage] = useState(null);
  const [selectedBranch, setSelectedBranch] = useState('ALL');
  const [selectedStatus, setSelectedStatus] = useState('ALL');
  const [activeTab, setActiveTab] = useState('list');
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [allBranches, setAllBranches] = useState(['ALL']);
  const [branchListData, setBranchListData] = useState([]);
  const [stats, setStats] = useState({
    totalEmp: 0,
    trained: 0,
    notTrained: 0,
    completionRate: 0,
  });
  const [apiParams, setApiParams] = useState({
    branchId: '',
    status: ''
  });

  // Base URL for images
  const baseURL = 'https://crmapi.repatriatepeoples.com';

  // Fetch branches on component mount.
  // NOTE: do NOT call fetchStaffData() here — the filter-change effect already
  // runs on mount and handles the initial data fetch, preventing a double call.
  useEffect(() => {
    fetchBranches();

    // Cleanup on unmount
    return () => {
      dispatch(resetGetStaffFaceTraining());
      dispatch(resetGetBranch());
    };
  }, [dispatch]);

  // Fetch staff data when filters change
  useEffect(() => {
    const params = {};
    if (selectedBranch !== 'ALL') {
      // Find branch ID from branch name using local state (Redux list is reset after fetch)
      const branch = branchListData.find(b => b.branchName === selectedBranch);
      if (branch) {
        params.branchId = branch.branchId;
      }
    }
    if (selectedStatus !== 'ALL') {
      params.status = selectedStatus === 'TRAINED' ? 'trained' : 'not_trained';
    }

    setApiParams(params);
    fetchStaffData(params);
  }, [selectedBranch, selectedStatus, branchListData]);

  const fetchStaffData = (params = {}) => {
    dispatch(getStaffFaceTrainingRequest(params));
  };

  const fetchBranches = () => {
    dispatch(getBranchRequest());
  };

  // Handle branches API response
  useEffect(() => {
    if (getBranchSuccess && getBranchList) {
      setBranchListData(getBranchList);
      const branches = ['ALL', ...getBranchList.map(branch => branch.branchName)];
      setAllBranches(branches);
      dispatch(resetGetBranch());
    }
    if (getBranchFailure) {
      console.error('Error fetching branches:', errorMessage);
      showMessage('error', `Failed to load branches: ${errorMessage || 'Unknown error'}`);
      dispatch(resetGetBranch());
    }
  }, [getBranchSuccess, getBranchFailure, errorMessage]);

  // Handle staff list API response
  // FIX Bug 1: API returns { data: [...], count: {...}, error: false }
  // so getStaffFaceTrainingList.data is the employee array (not data.data).
  // Also add getStaffFaceTrainingList to deps so stale-closure is impossible.
  useEffect(() => {
    if (getStaffFaceTrainingSuccess && getStaffFaceTrainingList?.data) {
      processAndFilterEmployees();
      updateStats();
    }
    if (getStaffFaceTrainingFailure) {
      console.error('Error fetching staff face training:', errorMessage);
      showMessage('error', `Failed to load face training data: ${errorMessage || 'Unknown error'}`);
    }
  }, [getStaffFaceTrainingSuccess, getStaffFaceTrainingFailure, getStaffFaceTrainingList, errorMessage]);

  // Helper function to get designation name from ID
  const getDesignationName = (designationId) => {
    // This should be replaced with actual designation mapping from your API
    const designationMap = {
      1: 'Administrator',
      2: 'Field Officer',
      3: 'Supervisor',
      4: 'Manager',
      5: 'Account Officer',
      6: 'Cashier',
      7: 'Loan Officer',
      8: 'Officer',
    };
    return designationMap[designationId] || `Designation ${designationId}`;
  };

  const processEmployeeData = (employeeData, index) => {
    // Parse images if they exist
    let images = [];
    let trainedImages = 0;

    if (employeeData?.faceTraining?.images) {
      try {
        if (typeof employeeData.faceTraining.images === 'string') {
          images = JSON.parse(employeeData.faceTraining.images);
        } else if (Array.isArray(employeeData.faceTraining.images)) {
          images = employeeData.faceTraining.images;
        }
        trainedImages = images.length;
      } catch (error) {
        console.error('Error parsing images:', error);
        images = [];
        trainedImages = 0;
      }
    }

    // ── BRANCH: the face-training endpoint often only returns branchId, not branchName.
    //    Look up the name from the branch list loaded separately.
    const branchId = employeeData.branchId || employeeData.branch_id;
    const resolvedBranchName =
      employeeData.branchName          // direct field (ideal)
      || employeeData.branch_name       // snake_case variant
      || employeeData.branch            // plain "branch" key
      || (branchId && branchListData.length > 0
          ? (branchListData.find(b => String(b.branchId) === String(branchId))?.branchName || null)
          : null)
      || 'UNKNOWN';

    // ── TRAINED BY: backend returns faceTraining.trainedBy (trainer's full name).
    //    Fallbacks kept for safety in case of alternate field names from the API.
    const ft = employeeData.faceTraining || {};
    const resolvedTrainedBy =
      ft.trainedBy
      || ft.trained_by
      || ft.trainerName
      || ft.trainer_name
      || ft.trainedByName
      || ft.trained_by_name
      || ft.createdByName
      || ft.created_by_name
      || ft.updatedByName
      || ft.updated_by_name
      || ft.adminName
      || ft.admin_name
      || ft.staffName     // e.g. if the API returns the staff name of trainer
      || null;

    return {
      id: employeeData.staffId,
      staffCode: employeeData.staffCode,
      name: employeeData.name,
      designationId: employeeData.designationId,
      designation: getDesignationName(employeeData.designationId),
      branch: resolvedBranchName,
      branchId: branchId || null,
      faceTrained: employeeData.trainingStatus === 'Face Trained',
      isTrained: employeeData.trainingStatus === 'Face Trained',
      trainedBy: resolvedTrainedBy || 'N/A',
      trainedOn: ft.trainedAt
        ? moment(ft.trainedAt).toDate()
        : null,
      trainedImages,
      imageCount: trainedImages,
      images: images.map((url, idx) => ({
        id: idx + 1,
        url: url.startsWith('http') ? url : `${baseURL}${url}`,
        date: ft.trainedAt ? moment(ft.trainedAt).toDate() : new Date(),
      })),
      profileImage: employeeData.staff_image
        ? `${baseURL}${employeeData.staff_image}`
        : noProfile,
      statusInfo: employeeData.statusInfo,
      modelVersion: ft.modelVersion,
      trainingAttempts: ft.trainingAttempts,
      lastTrainingError: ft.lastTrainingError,
      contactNo: employeeData.contactNo,
      emailId: employeeData.emailId,
      faceTraining: ft,
      trainingStatus: employeeData.trainingStatus,
      staffCreatedAt: employeeData.staffCreatedAt,
      staffUpdatedAt: employeeData.staffUpdatedAt,
    };
  };

  const processAndFilterEmployees = () => {
    // FIX Bug 1: API returns { data: [...employees], count: {...} }
    // so the employee array lives at .data, NOT .data.data
    if (!getStaffFaceTrainingList?.data) return;

    const employeeArray = Array.isArray(getStaffFaceTrainingList.data)
      ? getStaffFaceTrainingList.data
      : getStaffFaceTrainingList.data?.data || []; // fallback for nested structure

    if (employeeArray.length === 0) return;

    const processedEmployees = employeeArray.map((emp, idx) => processEmployeeData(emp, idx));

    const filtered = processedEmployees.filter((emp) => {
      // Client-side filtering (in addition to server-side)
      const branchMatch = selectedBranch === 'ALL' || emp.branch === selectedBranch;

      let statusMatch = true;
      if (selectedStatus === 'TRAINED') statusMatch = emp.faceTrained;
      if (selectedStatus === 'NOT_TRAINED') statusMatch = !emp.faceTrained;

      return branchMatch && statusMatch;
    });

    setFilteredEmployees(filtered);
  };

  const updateStats = () => {
    // FIX Bug 1: count is at .count not .data.count
    const count = getStaffFaceTrainingList?.count
      || getStaffFaceTrainingList?.data?.count; // fallback for nested structure
    if (!count) return;

    setStats({
      totalEmp: count.total_emp || 0,
      trained: count.number_of_face_trained || 0,
      notTrained: count.number_of_face_not_trained || 0,
      completionRate: count.face_trained_percentage || 0,
    });
  };

  const handleEmployeeClick = (employee) => {
    // Use the already processed employee data
    setSelectedEmployee(employee);
    setActiveTab('details');
  };

  const handleViewImages = (employee) => {
    setSelectedEmployee(employee);
    setShowImageModal(true);
  };

  const handleImageClick = (image) => {
    setSelectedImage(image);
  };

  const handleRefresh = () => {
    fetchStaffData(apiParams);
  };

  const handleBranchChange = (e) => {
    setSelectedBranch(e.target.value);
  };

  const handleStatusChange = (e) => {
    setSelectedStatus(e.target.value);
  };

  // Format date for display
  const formatDate = (date) => {
    if (!date) return 'N/A';
    return moment(date).format('DD-MMM-YYYY HH:mm');
  };

  // Format relative time
  const formatRelativeTime = (date) => {
    if (!date) return 'N/A';
    return moment(date).fromNow();
  };

  // Loading state
  if (isLoading && (!getStaffFaceTrainingList || getStaffFaceTrainingList.length === 0)) {
    return (
      <Container fluid className="py-5">
        <div className="d-flex justify-content-center align-items-center" style={{ minHeight: '400px' }}>
          <Spinner animation="border" role="status">
            <span className="visually-hidden">Loading...</span>
          </Spinner>
          <span className="ms-3">Loading face training data...</span>
        </div>
      </Container>
    );
  }

  return (
    <Container fluid className="py-3">
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <Card className="border-0 shadow-sm">
            <Card.Body className="p-4">
              <div className="d-flex align-items-center justify-content-between">
                <div>
                  <h2 className="mb-2">
                    <FaCamera className="me-3 text-primary" />
                    Face Recognition Training
                  </h2>
                  <p className="text-muted mb-0">View employee face recognition training status</p>
                </div>
                <Button 
                  variant="outline-primary" 
                  onClick={handleRefresh}
                  disabled={isLoading}
                >
                  <FaSync className={isLoading ? "me-2 fa-spin" : "me-2"} />
                  {isLoading ? 'Refreshing...' : 'Refresh'}
                </Button>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Stats Cards */}
      <Row className="mb-4">
        <Col xs={12} md={3}>
          <Card className="h-100 border-0 shadow-sm">
            <Card.Body className="text-center p-3">
              <div className="text-muted mb-2">Total Employees</div>
              <h1 className="display-6 mb-0">{stats.totalEmp}</h1>
              <small className="text-muted">All employees</small>
            </Card.Body>
          </Card>
        </Col>
        <Col xs={12} md={3}>
          <Card className="h-100 border-0 shadow-sm">
            <Card.Body className="text-center p-3">
              <div className="text-muted mb-2">Trained</div>
              <h1 className="display-6 text-success mb-0">{stats.trained}</h1>
              <small className="text-muted">Ready for recognition</small>
            </Card.Body>
          </Card>
        </Col>
        <Col xs={12} md={3}>
          <Card className="h-100 border-0 shadow-sm">
            <Card.Body className="text-center p-3">
              <div className="text-muted mb-2">Not Trained</div>
              <h1 className="display-6 text-danger mb-0">{stats.notTrained}</h1>
              <small className="text-muted">Need training</small>
            </Card.Body>
          </Card>
        </Col>
        <Col xs={12} md={3}>
          <Card className="h-100 border-0 shadow-sm">
            <Card.Body className="text-center p-3">
              <div className="text-muted mb-2">Completion Rate</div>
              <h1 className="display-6 text-primary mb-0">{stats.completionRate}%</h1>
              <ProgressBar now={stats.completionRate} className="mt-2" variant="primary" style={{ height: '6px' }} />
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Main Content with Tabs */}
      <Row className="mb-4">
        <Col>
          <Card className="border-0 shadow-sm">
            <Card.Body className="p-0">
              <div className="p-3 border-bottom">
                <Row className="align-items-center">
                  <Col xs={12} md={6} lg={8}>
                    <Tabs 
                      activeKey={activeTab} 
                      onSelect={(k) => setActiveTab(k)} 
                      className="mb-0"
                    >
                      <Tab 
                        eventKey="list" 
                        title={
                          <span className="fw-bold">
                            Employee List ({filteredEmployees.length})
                          </span>
                        }
                        tabClassName="me-3"
                      />
                      <Tab 
                        eventKey="details" 
                        title={
                          <span className="fw-bold">
                            Training Details
                          </span>
                        }
                        disabled={!selectedEmployee}
                        tabClassName="me-3"
                      />
                    </Tabs>
                  </Col>
                  <Col xs={12} md={6} lg={4}>
                    <Row className="g-2">
                      <Col xs={6}>
                        <Form.Select 
                          value={selectedBranch} 
                          onChange={handleBranchChange}
                          size="sm"
                          className="border"
                        >
                          {allBranches.map((branch) => (
                            <option key={branch} value={branch}>
                              {branch === 'ALL' ? 'All Branches' : branch}
                            </option>
                          ))}
                        </Form.Select>
                      </Col>
                      <Col xs={6}>
                        <Form.Select 
                          value={selectedStatus} 
                          onChange={handleStatusChange}
                          size="sm"
                          className="border"
                        >
                          <option value="ALL">All Status</option>
                          <option value="TRAINED">Trained</option>
                          <option value="NOT_TRAINED">Not Trained</option>
                        </Form.Select>
                      </Col>
                    </Row>
                  </Col>
                </Row>
              </div>

              {activeTab === 'list' && (
                <div className="p-4">
                  {filteredEmployees.length === 0 ? (
                    <div className="text-center py-5">
                      <FaUser size={64} className="text-muted mb-3" />
                      <h4 className="text-muted">No Employees Found</h4>
                      <p className="text-muted">Try changing your filter criteria</p>
                    </div>
                  ) : (
                    <Row className="g-4">
                      {filteredEmployees.map((employee, index) => (
                        <Col key={employee.id || `emp-${index}`} xs={12} sm={6} md={4} lg={3}>
                          <Card
                            className={`h-100 cursor-pointer border ${
                              selectedEmployee?.id === employee.id ? 'border-primary border-2 shadow-sm' : 'border-light'
                            }`}
                            onClick={() => handleEmployeeClick(employee)}
                            style={{
                              transition: 'all 0.2s',
                              minHeight: '380px',
                            }}
                          >
                            <Card.Body className="p-3 text-center d-flex flex-column justify-content-between">
                              {/* Employee Image */}
                              <div className="position-relative d-inline-block mb-3">
                                <Image
                                  src={employee.profileImage}
                                  roundedCircle
                                  width={100}
                                  height={100}
                                  crossOrigin='anonymous'
                                  className="border object-fit-cover"
                                  style={{ objectFit: 'cover' }}
                                  onError={(e) => {
                                    e.target.onerror = null;
                                    e.target.src = noProfile;
                                  }}
                                />
                                {employee.faceTrained && (
                                  <Badge
                                    bg="success"
                                    className="position-absolute rounded-circle p-1 border border-white"
                                    style={{ bottom: '5px', right: '5px' }}
                                  >
                                    <FaCheckCircle size={12} />
                                  </Badge>
                                )}
                              </div>

                              {/* Employee Details */}
                              <div className="mb-3">
                                {/* Employee Name */}
                                <h6 className="mb-2 fw-bold text-truncate" style={{ fontSize: '1rem' }}>
                                  {employee.name || 'N/A'}
                                </h6>

                                {/* Employee ID */}
                                <div className="mb-2">
                                  <Badge bg="light" text="dark" className="px-2 py-1 rounded">
                                    <FaIdCard className="me-1" />
                                    ID: {employee.staffCode || 'N/A'}
                                  </Badge>
                                </div>

                                {/* Designation */}
                                <div className="mb-2">
                                  <small className="text-muted">
                                    <strong>Designation:</strong> {employee.designation || 'N/A'}
                                  </small>
                                </div>

                                {/* Branch */}
                                <div className="mb-2">
                                  <small className="text-muted">
                                    <FaBuilding className="me-1" />
                                    {employee.branch || 'N/A'}
                                  </small>
                                </div>

                                {/* Status Badge with custom colors from API */}
                                <div className="mb-3">
                                  <Badge
                                    style={{
                                      backgroundColor: employee.statusInfo?.color
                                        ? `#${employee.statusInfo.color.substring(6)}`
                                        : employee.faceTrained
                                        ? '#28a745'
                                        : '#dc3545',
                                      color: employee.statusInfo?.textColor 
                                        ? `#${employee.statusInfo.textColor.substring(6)}` 
                                        : 'white',
                                    }}
                                    className="px-2 py-1 rounded"
                                  >
                                    {employee.statusInfo?.statusLabel || 
                                      (employee.faceTrained ? 'Trained' : 'Not Trained')}
                                  </Badge>
                                </div>
                              </div>

                              {/* Image Count */}
                              <div className="mt-3">
                                <small className="text-muted d-block" style={{ fontSize: '0.8rem' }}>
                                  <FaImages className="me-1" />
                                  Images: {employee.trainedImages || 0}/3
                                </small>
                              </div>
                            </Card.Body>
                          </Card>
                        </Col>
                      ))}
                    </Row>
                  )}
                </div>
              )}

              {activeTab === 'details' && selectedEmployee && (
                <div className="p-4">
                  <Row>
                    <Col lg={4}>
                      <Card className="mb-3 border-0 shadow-sm">
                        <Card.Body className="text-center p-4">
                          <div className="position-relative d-inline-block mb-4">
                            <Image
                              src={selectedEmployee.profileImage}
                              roundedCircle
                              crossOrigin='anonymous'
                              width={150}
                              height={150}
                              className="border object-fit-cover"
                              style={{ objectFit: 'cover' }}
                              onError={(e) => {
                                e.target.onerror = null;
                                e.target.src = noProfile;
                              }}
                            />
                            {selectedEmployee.faceTrained && (
                              <Badge
                                bg="success"
                                className="position-absolute rounded-circle p-2 border border-white"
                                style={{ bottom: '15px', right: '15px' }}
                              >
                                <FaCheckCircle size={20} />
                              </Badge>
                            )}
                          </div>

                          <h4 className="mb-2" style={{ fontSize: '1.3rem', fontWeight: '600' }}>
                            {selectedEmployee.name || 'N/A'}
                          </h4>

                          <div className="mb-3">
                            <Badge bg="info" className="px-3 py-2 rounded-pill me-2">
                              <FaUser className="me-2" />
                              ID: {selectedEmployee.staffCode || 'N/A'}
                            </Badge>
                          </div>

                          <div className="mb-2">
                            <p className="text-muted mb-1">
                              <strong>Designation:</strong> {selectedEmployee.designation || 'N/A'}
                            </p>
                          </div>

                          <div className="mb-2">
                            <p className="text-muted mb-1">
                              <FaBuilding className="me-2" />
                              <strong>Branch:</strong> {selectedEmployee.branch || 'N/A'}
                            </p>
                          </div>

                          <div className="mb-2">
                            <p className="text-muted mb-1">
                              <strong>Contact:</strong> {selectedEmployee.contactNo || 'N/A'}
                            </p>
                          </div>

                          <div className="mb-2">
                            <p className="text-muted mb-1">
                              <strong>Email:</strong> {selectedEmployee.emailId || 'N/A'}
                            </p>
                          </div>

                          <div className="mb-4">
                            <Badge
                              style={{
                                backgroundColor: selectedEmployee.statusInfo?.color
                                  ? `#${selectedEmployee.statusInfo.color.substring(6)}`
                                  : selectedEmployee.faceTrained
                                  ? '#28a745'
                                  : '#dc3545',
                                color: selectedEmployee.statusInfo?.textColor
                                  ? `#${selectedEmployee.statusInfo.textColor.substring(6)}`
                                  : 'white',
                              }}
                              className="px-4 py-3 rounded-pill"
                            >
                              {selectedEmployee.statusInfo?.statusLabel || 
                                (selectedEmployee.faceTrained ? 'Trained' : 'Not Trained')}
                            </Badge>
                          </div>

                          <div className="mt-4">
                            {selectedEmployee.faceTrained ? (
                              <>
                                <Badge bg="success" className="px-4 py-3 mb-3 rounded-pill" style={{ fontSize: '1rem' }}>
                                  <FaCheckCircle className="me-2" />
                                  Face Trained
                                </Badge>
                                <Button
                                  variant="outline-primary"
                                  className="w-100 mt-3 py-2"
                                  onClick={() => handleViewImages(selectedEmployee)}
                                >
                                  <FaImages className="me-2" />
                                  View Images ({selectedEmployee.trainedImages || 0}/3)
                                </Button>
                              </>
                            ) : (
                              <>
                                <Badge bg="danger" className="px-4 py-3 mb-3 rounded-pill" style={{ fontSize: '1rem' }}>
                                  <FaTimesCircle className="me-2" />
                                  Not Trained
                                </Badge>
                                <Alert variant="warning" className="mt-3">
                                  <FaExclamationTriangle className="me-2" />
                                  Employee face not trained. Contact administrator for training.
                                </Alert>
                              </>
                            )}
                          </div>
                        </Card.Body>
                      </Card>
                    </Col>

                    <Col lg={8}>
                      {selectedEmployee.faceTrained ? (
                        <Card className="border-0 shadow-sm h-100">
                          <Card.Body className="p-4">
                            <h5 className="mb-4 d-flex align-items-center" style={{ fontSize: '1.25rem' }}>
                              <FaCheckCircle className="me-3 text-success" />
                              Training Details
                            </h5>

                            <Row>
                              <Col md={6}>
                                <Card className="border h-100">
                                  <Card.Body className="p-4">
                                    <h6 className="mb-3" style={{ fontSize: '1.1rem' }}>
                                      Training Information
                                    </h6>
                                    <ListGroup variant="flush">
                                      <ListGroup.Item className="d-flex justify-content-between py-3 border-bottom">
                                        <span className="text-muted">Model Version:</span>
                                        <span className="fw-bold">{selectedEmployee.modelVersion || 'N/A'}</span>
                                      </ListGroup.Item>
                                      <ListGroup.Item className="d-flex justify-content-between py-3 border-bottom">
                                        <span className="text-muted">Designation:</span>
                                        <span className="fw-bold">{selectedEmployee.designation || 'N/A'}</span>
                                      </ListGroup.Item>
                                      <ListGroup.Item className="d-flex justify-content-between py-3 border-bottom">
                                        <span className="text-muted">Trained By:</span>
                                        <span className="fw-bold">{selectedEmployee.trainedBy || 'N/A'}</span>
                                      </ListGroup.Item>
                                      <ListGroup.Item className="d-flex justify-content-between py-3 border-bottom">
                                        <span className="text-muted">Training Date:</span>
                                        <span className="fw-bold">
                                          {formatDate(selectedEmployee.trainedOn)}
                                        </span>
                                      </ListGroup.Item>
                                      <ListGroup.Item className="d-flex justify-content-between py-3 border-bottom">
                                        <span className="text-muted">Images Trained:</span>
                                        <Badge bg="info" className="fs-6 px-3 py-2">
                                          {selectedEmployee.trainedImages || 0}/3
                                        </Badge>
                                      </ListGroup.Item>
                                      <ListGroup.Item className="d-flex justify-content-between py-3 border-bottom">
                                        <span className="text-muted">Training Attempts:</span>
                                        <span>{selectedEmployee.trainingAttempts || 0}</span>
                                      </ListGroup.Item>
                                      <ListGroup.Item className="d-flex justify-content-between py-3">
                                        <span className="text-muted">Last Updated:</span>
                                        <span>
                                          {formatRelativeTime(selectedEmployee.trainedOn)}
                                        </span>
                                      </ListGroup.Item>
                                    </ListGroup>
                                  </Card.Body>
                                </Card>
                              </Col>
                              <Col md={6} className="mt-4 mt-md-0">
                                <Card className="border h-100">
                                  <Card.Body className="p-4">
                                    <h6 className="mb-3" style={{ fontSize: '1.1rem' }}>
                                      Training Progress
                                    </h6>
                                    <div className="text-center">
                                      <div className="display-4 text-primary mb-3">
                                        {(((selectedEmployee.trainedImages || 0) / 3) * 100).toFixed(0)}%
                                      </div>
                                      <ProgressBar
                                        now={((selectedEmployee.trainedImages || 0) / 3) * 100}
                                        variant={(selectedEmployee.trainedImages || 0) === 3 ? 'success' : 'warning'}
                                        className="mb-3"
                                        style={{ height: '12px' }}
                                      />
                                      <p className="text-muted mb-3" style={{ fontSize: '0.95rem' }}>
                                        {(selectedEmployee.trainedImages || 0) === 3
                                          ? '✓ All 3 images trained successfully'
                                          : `${selectedEmployee.trainedImages || 0} of 3 images trained`}
                                      </p>
                                      {(selectedEmployee.trainedImages || 0) === 3 && (
                                        <Alert variant="success" className="mt-3 mb-0">
                                          <FaCheckCircle className="me-2" />
                                          Face fully trained and ready for recognition
                                        </Alert>
                                      )}
                                      {selectedEmployee.lastTrainingError && (
                                        <Alert variant="warning" className="mt-3">
                                          <FaExclamationTriangle className="me-2" />
                                          Last training error: {selectedEmployee.lastTrainingError}
                                        </Alert>
                                      )}
                                    </div>
                                  </Card.Body>
                                </Card>
                              </Col>
                            </Row>
                          </Card.Body>
                        </Card>
                      ) : (
                        <Card className="border-0 shadow-sm h-100">
                          <Card.Body className="text-center py-5 px-4">
                            <div className="mb-4">
                              <FaRegSmile size={80} className="text-muted opacity-50" />
                            </div>
                            <h3 className="text-muted mb-3">Face Not Trained</h3>
                            <p className="text-muted mb-4 fs-5">
                              This employee's face has not been trained for recognition yet.
                              Please contact your administrator for training.
                            </p>
                            <div className="mb-4">
                              <p className="text-muted">
                                <strong>Designation:</strong> {selectedEmployee.designation || 'N/A'}
                              </p>
                            </div>
                            <Alert variant="info" className="mb-0 mx-auto" style={{ maxWidth: '500px' }}>
                              <FaExclamationTriangle className="me-2" />
                              <strong>Training Requirement:</strong> Exactly 3 images are required for training
                            </Alert>
                          </Card.Body>
                        </Card>
                      )}
                    </Col>
                  </Row>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Images Modal */}
      <Modal show={showImageModal} onHide={() => setShowImageModal(false)} size="xl" centered>
        <Modal.Header closeButton className="bg-info text-white">
          <Modal.Title className="d-flex align-items-center">
            <FaImages className="me-3" />
            <div>
              <div>Trained Images</div>
              <small className="fs-6 opacity-75">
                {selectedEmployee?.name || 'N/A'}({selectedEmployee?.trainedImages || 0}/3 images)
              </small>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Modal.Body className="p-4">
          {selectedEmployee?.images && selectedEmployee.images.length > 0 ? (
            <>
              {selectedImage && (
                <div className="text-center mb-4 p-3 bg-light rounded">
                  <Image
                    src={selectedImage.url}
                    rounded
                    crossOrigin="anonymous"
                    className="mb-3"
                    style={{ maxHeight: '250px', maxWidth: '100%', objectFit: 'contain' }}
                    onError={(e) => {
                      e.target.onerror = null;
                      e.target.src = noProfile;
                    }}
                  />
                  <p className="text-muted mb-0">
                    Uploaded:{' '}
                    {selectedImage.date ? moment(selectedImage.date).format('DD-MMM-YYYY HH:mm:ss') : 'Date not available'}
                  </p>
                </div>
              )}

              <h6 className="mb-3">All Training Images</h6>
              <Row className="g-2">
                {selectedEmployee.images.map((image, index) => (
                  <Col key={image.id || `img-${index}`} xs={6} sm={4} md={3} lg={2}>
                    <Card
                      className={`cursor-pointer border ${selectedImage?.id === image.id ? 'border-primary border-2' : ''}`}
                      onClick={() => handleImageClick(image)}
                    >
                      <Card.Body className="text-center p-2">
                        <Image
                          src={image.url}
                          thumbnail
                          crossOrigin="anonymous"
                          className="mb-2"
                          style={{ width: '100%', height: '80px', objectFit: 'cover' }}
                          onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = noProfile;
                          }}
                        />
                        <small className="text-muted d-block">Image {index + 1}</small>
                        {image.date && <small className="text-muted">{moment(image.date).format('HH:mm')}</small>}
                      </Card.Body>
                    </Card>
                  </Col>
                ))}
              </Row>
            </>
          ) : (
            <div className="text-center py-5">
              <FaImages size={80} className="text-muted mb-3 opacity-50" />
              <h5 className="text-muted mb-2">No Images Found</h5>
              <p className="text-muted">This employee doesn't have any trained face images yet.</p>
            </div>
          )}
        </Modal.Body>
        <Modal.Footer className="border-top-0">
          <Button variant="light" onClick={() => setShowImageModal(false)} className="px-4">
            Close
          </Button>
          {selectedEmployee?.images && selectedEmployee.images.length > 0 && (
            <Button variant="info" className="px-4">
              <FaDownload className="me-2" />
              Download All
            </Button>
          )}
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default Index;